fields.InputDefinition:
{
  "goal": "Assume you are already logged in at http://localhost:4200. Open the AI application using the application switcher dropdown next to the logo (NOT the Ctrl+K search box), then open the Agent Requests section. If any request cards are listed, click a request card to open its detail dialog. Pages can take 10-30s to load in this resource-constrained environment - wait, don't navigate away. Success is that clicking a request card opens a detail dialog/panel showing the full request, and for an actionable (pending/'Requested') request it presents response controls such as Approve / Reject / Respond. Seeing the request detail dialog render with its action controls is success - you do NOT need to actually approve or reject. If there are no requests, a valid 'No agent requests yet' empty state counts.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "minConfidence": 0.7,
  "maxSteps": 35,
  "judgeValidationCriteria": [
    "The Agent Requests list renders (cards with type/priority/status), OR a valid empty state ('No agent requests yet')",
    "Clicking a request card opens a detail dialog/panel; for an actionable request, Approve/Reject/Respond controls are visible",
    "No error messages, blank screens, or crash pages"
  ]
}
